import{_ as t,o as r,c as o,a2 as a}from"./chunks/framework.C8nVztS1.js";const c=JSON.parse('{"title":"Explore — alternate browsers","description":"Perf-oriented spike for Astral, Thirtyfour, Chromiumoxide — out of scope for 1.0.","frontmatter":{"title":"Explore — alternate browsers","description":"Perf-oriented spike for Astral, Thirtyfour, Chromiumoxide — out of scope for 1.0.","outline":"deep"},"headers":[],"relativePath":"guide/explore-browsers.md","filePath":"guide/explore-browsers.md","lastUpdated":1789825651000}'),s={name:"guide/explore-browsers.md"};function n(i,e,d,l,h,p){return r(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="explore-—-alternate-browsers" tabindex="-1">Explore — alternate browsers <a class="header-anchor" href="#explore-—-alternate-browsers" aria-label="Permalink to &quot;Explore — alternate browsers&quot;">​</a></h1><p>One-time spike before 1.0: could a <strong>faster</strong> browser backend beat Playwright on mass recipe e2e (leased URL, many workers)?</p><p><strong>Decision for 1.0:</strong> stay on Playwright. Revisit when real perf dogfood needs throughput beyond Node CDP bindings — not because Playwright “already has CDP.”</p><table tabindex="0"><thead><tr><th>Project</th><th>Perf angle</th><th>Why not in 1.0</th></tr></thead><tbody><tr><td><a href="https://github.com/lino-levan/astral" target="_blank" rel="noreferrer">Astral</a> (Deno)</td><td>Lean Deno browser automation</td><td>No Node/Vitest dogfood path without a separate runner</td></tr><tr><td><a href="https://github.com/stevepryde/thirtyfour" target="_blank" rel="noreferrer">Thirtyfour</a> (Rust / WebDriver)</td><td>Native Rust client</td><td>WebDriver stack + Node bridge; unclear win vs CDP for our recipe shape</td></tr><tr><td><a href="https://github.com/mattsse/chromiumoxide" target="_blank" rel="noreferrer">Chromiumoxide</a> (Rust / CDP)</td><td>Low-level Rust CDP for raw throughput</td><td>Interesting <strong>because</strong> it is CDP — potentially faster than Playwright’s Node layer. Deferred for Node↔Rust integration cost in the Vitest/Playwright recipe path until there is concrete perf dogfood</td></tr></tbody></table><p>A thin recipe that only returns <code>{ url }</code> could sit under any browser client later. That is not worth a first-class adapter until something measures better than Playwright on real suites.</p><p><strong>Do not block 1.0</strong> on shipping these.</p><p>Related: <a href="/untestutils/guide/browser-mode">Vitest Browser Mode</a> (component-in-browser track — also not recipe-e2e).</p>',7)])])}const f=t(s,[["render",n]]);export{c as __pageData,f as default};
